void
MyDelay (void)
{
	for (uint32_t i = 0; i < 160000; i++);
}


void
Flash (uint8_t n)
{
	for (uint8_t i = 0; i < n; i++)
	{
		DigWrite ('A', USER_LED_PIN, LOW);
		MyDelay ();
		DigWrite ('A', USER_LED_PIN, HIGH);
		MyDelay ();
	}

	DigWrite ('A', USER_LED_PIN, LOW);
}



